cmd = r'''python3 - <<'PY'
import os, json, hashlib
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
orig='/root/data/workbook.xlsx'
wb=load_workbook(path,data_only=False)
wbo=load_workbook(orig,data_only=False)
print('Reopened sheets:', wb.sheetnames)
print('No new sheets:', wb.sheetnames == wbo.sheetnames)
ws=wb['Task']
# Print sample formulas / ranges
sample_cells = ['H12','I12','L17','H19','L24','H26','L31','H35','L40','H42','H43','H44','H45','H46','H47','H50','L50']
for addr in sample_cells:
    print(f'{addr}={ws[addr].value!r}')
# Verify all target cells are formulas starting '='
targets=[]
for r1,r2 in [(12,17),(19,24),(26,31),(35,40),(42,47)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            targets.append((r,c))
for c in range(8,13):
    targets.append((50,c))
non_formula=[]
for r,c in targets:
    v=ws.cell(r,c).value
    if not (isinstance(v,str) and v.startswith('=')):
        non_formula.append(f'{get_column_letter(c)}{r}={v!r}')
print('Target formula count:', len(targets))
print('Non-formula target cells:', non_formula)
# Verify cells outside specified H:L target ranges not modified by comparing formulas/values and style ids.
allowed=set(targets)
value_diffs=[]
style_diffs=[]
for sname in wb.sheetnames:
    ws1=wb[sname]
    ws0=wbo[sname]
    max_row=max(ws1.max_row, ws0.max_row)
    max_col=max(ws1.max_column, ws0.max_column)
    for r in range(1,max_row+1):
        for c in range(1,max_col+1):
            coord=(r,c)
            if sname=='Task' and coord in allowed:
                continue
            v1=ws1.cell(r,c).value
            v0=ws0.cell(r,c).value
            if v1 != v0:
                value_diffs.append(f'{sname}!{get_column_letter(c)}{r}: {v0!r}->{v1!r}')
            if ws1.cell(r,c).style_id != ws0.cell(r,c).style_id:
                style_diffs.append(f'{sname}!{get_column_letter(c)}{r}: {ws0.cell(r,c).style_id}->{ws1.cell(r,c).style_id}')
# Also verify target cell styles unchanged
for r,c in allowed:
    if ws.cell(r,c).style_id != wbo['Task'].cell(r,c).style_id:
        style_diffs.append(f'Task!{get_column_letter(c)}{r}: {wbo["Task"].cell(r,c).style_id}->{ws.cell(r,c).style_id}')
print('Outside allowed value diffs count:', len(value_diffs))
if value_diffs[:20]: print('\n'.join(value_diffs[:20]))
print('Style diffs count:', len(style_diffs))
if style_diffs[:20]: print('\n'.join(style_diffs[:20]))
# Check formula templates include allowed patterns and expected ranges
bad=[]
for r,c in targets:
    v=ws.cell(r,c).value
    if r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
        if 'INDEX(' not in v or 'MATCH(' not in v or 'Data!$H$21:$L$38' not in v or 'Data!$D$21:$D$38' not in v or 'Data!$H$4:$L$4' not in v:
            bad.append(f'{get_column_letter(c)}{r}:{v}')
print('Lookup formulas with unexpected pattern:', bad[:10], 'count', len(bad))
PY'''
print(terminal(cmd, timeout=120)['output'])"}
